{
  "queries": [
    {
      "doc_id": "SOP-P1-L4-05",
      "query": "Please confirm who approved the planned shutdown procedure for the Heat Treat line and provide the date of approval. If there have been revisions, list them and supply the revision history with signatures or electronic approval evidence."
    },
    {
      "doc_id": "SOP-P3-L1-04",
      "query": "I need a checklist of required documentation and mandatory verbal points for shift handover on the Hot Forge line. Also indicate any control measures for abnormal condition escalation and where the handover records are retained."
    },
    {
      "doc_id": "SOP-P2-L2-03",
      "query": "For first-article inspection on the Ring Rolling line: what are the acceptance criteria and sampling steps? Provide the required forms and evidence of calibration status for measuring equipment used."
    },
    {
      "doc_id": "QS-PROC-06",
      "query": "Describe how forging temperature control is verified during production (controls, monitoring frequency, and record retention). Are there defined corrective actions when temperatures fall outside limits?"
    },
    {
      "doc_id": "QS-CFW-8404-30",
      "query": "Supply the quality acceptance criteria and measurement points for flange blank CFW-8404-30 (material 4140). Also indicate if any special heat treatment or traceability requirements are specified."
    },
    {
      "doc_id": "ECN-2026-023",
      "query": "What exactly changes to the Hot Forge radial ring rolling mill #1 under this ECN? Provide effective date, affected procedures, and evidence that training/validation was completed post-change."
    },
    {
      "doc_id": "ECN-2026-022",
      "query": "Summarize the modification described for machining induction billet heater #1. What risk assessments were performed and where are the associated test reports or acceptance records filed?"
    },
    {
      "doc_id": "QS-CFW-1140-78",
      "query": "For axle hub CFW-1140-78 (4140), list dimensional tolerances, surface finish requirements, and nonconformance acceptance limits. Also flag any special inspection steps or NDT requirements."
    },
    {
      "doc_id": "ECN-2026-013",
      "query": "Detail the scope and rationale for the change to Hot Forge induction billet heater #2. Were process parameters updated (e.g., temperature profiles)? Provide evidence of approval and implementation schedule."
    },
    {
      "doc_id": "ECN-2026-002",
      "query": "What are the implemented changes to Heat Treat furnace #3 in this ECN? Include any impacts to cycle recipes, thermocouple placement, or monitoring systems, and confirm where validation records are stored."
    },
    {
      "doc_id": "SOP-P3-L2-04",
      "query": "Provide the required elements of a shift handover on the Ring Rolling line. Are there mandatory sign-offs, and what items must be communicated about in-process pieces and tooling status?"
    },
    {
      "doc_id": "QS-CFW-7855-84",
      "query": "What are the quality specifications for valve body CFW-7855-84 (F316)? Include chemical, mechanical, and finishing requirements plus any specific traceability or certification needed from suppliers."
    },
    {
      "doc_id": "SOP-P3-L2-05",
      "query": "For a planned shutdown of the Ring Rolling line, what is the stepwise procedure, required permits, and post-shutdown checks? Please provide the approval matrix and required safety brief evidence."
    },
    {
      "doc_id": "QS-CFW-1476-90",
      "query": "List inspection criteria and critical dimensions for connecting rod CFW-1476-90 (1045). Are there required hardness or microstructure checks, and where are acceptance records archived?"
    },
    {
      "doc_id": "QS-CFW-6417-61",
      "query": "For bearing ring CFW-6417-61 (52100), detail surface finish, dimensional tolerances, and any heat-treatment hardness ranges. Also indicate if runout or concentricity tests are required."
    },
    {
      "doc_id": "SOP-P3-L4-05",
      "query": "Compare this Planned shutdown - Heat Treat line SOP to SOP-P1-L4-05: what differences exist in responsibilities, isolation steps, and restoration verification? Provide rationale for any deviations."
    },
    {
      "doc_id": "ECN-2026-021",
      "query": "Describe the change to machining hydraulic forging press #2. Were safety interlocks or guards modified? Please provide the change approval, risk assessment, and evidence of operator training post-change."
    },
    {
      "doc_id": "QS-PROC-10",
      "query": "What are the machining surface finish requirements under QS-PROC-10 (P2)? Include measurement methods, instruments, acceptance limits, and required calibration evidence for roughness testers."
    },
    {
      "doc_id": "SOP-P1-L3-01",
      "query": "Outline the line startup steps for the Machining line, including pre-start checks, required signatures, and hold points before production acceptance. Where are startup records stored and how long retained?"
    },
    {
      "doc_id": "SOP-P3-L2-02",
      "query": "For product changeover on the Ring Rolling line: what are the setup verification steps and first-piece inspection requirements? Provide the required approvals and criteria to resume normal production."
    }
  ]
}
